select 'db_now', now();
select 'incident', incident_id, state, lifecycle, mode, control_generation, created_at, closed_at, related_incident_id from opspilot_incidents where incident_id='65b0490a-df80-51b2-adfa-698c53a9ee7b';
select 'run', run_id, state, epoch, budget_limit, budget_spent, budget_unknown, budget_reserved, tool_operations_used, tool_seconds_used, control_generation, deadline from opspilot_runs where run_id='50936b1d-2e18-5f18-8dd1-caa0afcd84f9';
select 'step', sequence, step_id, logical_key, status, control_generation, observed_at, coalesce(response->>'kind', 'model_turn'), response->>'finish_reason', response->>'response_model', response->'usage', (select string_agg((t->>'tool') || ':' || coalesce(t->>'status',''), ',') from jsonb_array_elements(tool_results) t) from opspilot_steps where run_id='50936b1d-2e18-5f18-8dd1-caa0afcd84f9' order by sequence;
select 'evidence', evidence_id, step_id_hint, status, adopted, committed, payload_state, observed_at, data_as_of, view->>'tool', view->>'status', view->>'returned_count', view->>'truncated', raw_sha256 from (select e.*, split_part(evidence_id, '-t', 1) as step_id_hint from opspilot_evidence e where run_id='50936b1d-2e18-5f18-8dd1-caa0afcd84f9') x order by observed_at;
select 'budget_reservation', reservation_id, amount, state, reserved_seconds, seconds from opspilot_budget_reservations where run_id='50936b1d-2e18-5f18-8dd1-caa0afcd84f9' order by reservation_id;
select 'tool_charge', dispatch_id, epoch, operation_id, reserved, seconds from opspilot_tool_charges where run_id='50936b1d-2e18-5f18-8dd1-caa0afcd84f9' order by operation_id;
select 'subject_event', subject_id, sequence, kind, recorded_at, case when kind = 'intake_accepted' then (payload - 'question')::text || ' [question omitted, sha256 ' || encode(sha256(convert_to(payload->>'question','UTF8')),'hex') || ']' else payload::text end from opspilot_subject_events where subject_id in ('65b0490a-df80-51b2-adfa-698c53a9ee7b','50936b1d-2e18-5f18-8dd1-caa0afcd84f9') order by recorded_at;
select 'control', created_at, action, actor, (payload - 'idempotency_key')::text || ' [idempotency_key omitted]', expected_generation, resulting_generation from opspilot_controls where incident_id='65b0490a-df80-51b2-adfa-698c53a9ee7b' order by created_at;
select 'delivery', received_at, status, outcome, actor, starts_at from opspilot_alert_deliveries where incident_id='65b0490a-df80-51b2-adfa-698c53a9ee7b' order by received_at;
select 'observation_ending', ending_id, session_id, ended_reason, transition, lifecycle_before, lifecycle_after, recorded_at from opspilot_observation_endings where incident_id='65b0490a-df80-51b2-adfa-698c53a9ee7b' order by recorded_at;
select 'postmortem', postmortem_id, generation, latest_version, created_at, updated_at from opspilot_postmortems where incident_id='65b0490a-df80-51b2-adfa-698c53a9ee7b';
select 'postmortem_version', v.version, v.state, v.created_at, v.generated_by, v.generated_by_kind, v.run_count, v.last_run_id, v.observation_session_id, v.incident_control_generation, length(v.content), v.content_sha256 from opspilot_postmortem_versions v join opspilot_postmortems p using (postmortem_id) where p.incident_id='65b0490a-df80-51b2-adfa-698c53a9ee7b' order by v.version;
select 'postmortem_attempt', attempt_id, status, error_code, version, model, response_model, model_requests, prompt_tokens, completion_tokens, started_at, finished_at from opspilot_postmortem_generation_attempts where incident_id='65b0490a-df80-51b2-adfa-698c53a9ee7b' order by started_at;
select 'knowledge_entries', count(*) from opspilot_knowledge_entries;
select 'trace_outbox_rows_for_incident', count(*) from opspilot_trace_outbox where incident_id='65b0490a-df80-51b2-adfa-698c53a9ee7b';
select 'open_or_inflight', (select count(*) from opspilot_incidents where lifecycle <> 'closed'), (select count(*) from opspilot_runs where state in ('queued','running','waiting_human')), (select count(*) from opspilot_observation_sessions where state not in ('completed','expired','cancelled'));
select 'trace_outbox', kind, state, drop_reason, count(*), min(created_at), max(created_at) from opspilot_trace_outbox where incident_id='65b0490a-df80-51b2-adfa-698c53a9ee7b' group by 2,3,4 order by 2,3;
